(() => {
  const carousel = document.querySelector('.activity-card-carousel[data-carousel]');
  const track = carousel?.querySelector('.carousel-track');
  if (!track || track.querySelector('[data-extra-bath-slide]')) return;
  const slides = [
    { src: 'data:image/jpeg;base64,', alt: '私人戶外湯屋實景', caption: '私人戶外湯屋' },
    { src: 'data:image/jpeg;base64,', alt: '日式澡堂實景', caption: '日式澡堂' }
  ];
  for (const item of slides) {
    const slide = document.createElement('div');
    slide.className = 'slide';
    slide.setAttribute('data-extra-bath-slide', 'true');
    const img = document.createElement('img');
    img.src = item.src;
    img.alt = item.alt;
    const caption = document.createElement('div');
    caption.className = 'slide-caption';
    caption.textContent = item.caption;
    slide.append(img, caption);
    track.appendChild(slide);
  }
})();